<?php
namespace Modules\Ran\Reports;
class StockMovementReport extends AbstractRanReport{public function title():string{return 'Stock Movements';}public function headings():array{return ['Date/Time','Type','Item','Lot','Qty In','Qty Out','Weight In','Weight Out','Reference'];}public function rows(array $f):array{$q=\DB::table('ran_stock_movements as m')->join('ran_items as i','i.id','=','m.item_id')->leftJoin('ran_stock_lots as l','l.id','=','m.stock_lot_id')->whereNull('m.deleted_at');$this->filter($q,$f,'m.movement_at','m');return $q->orderByDesc('m.movement_at')->get(['m.movement_at','m.movement_type','i.name as item','l.lot_no','m.quantity_in','m.quantity_out','m.weight_in','m.weight_out','m.reference_no'])->map(fn($r)=>(array)$r)->all();}public function totals(array $rows):array{return ['Qty In'=>array_sum(array_column($rows,'quantity_in')),'Qty Out'=>array_sum(array_column($rows,'quantity_out')),'Weight In'=>array_sum(array_column($rows,'weight_in')),'Weight Out'=>array_sum(array_column($rows,'weight_out'))];}}
